def solve():
    tiles_str = input().split()
    tiles = []
    for t_str in tiles_str:
        tiles.append((int(t_str[0]), t_str[1]))

    def check_mentsu(hand):
        if len(hand) < 3:
            return False

        n = len(hand)
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    t1_num, t1_suit = hand[i]
                    t2_num, t2_suit = hand[j]
                    t3_num, t3_suit = hand[k]

                    # Check for koutsu
                    if t1_num == t2_num and t2_num == t3_num and t1_suit == t2_suit and t2_suit == t3_suit:
                        return True

                    # Check for shuntsu
                    if t1_suit == t2_suit and t2_suit == t3_suit:
                        nums = sorted([t1_num, t2_num, t3_num])
                        if nums[0] + 1 == nums[1] and nums[1] + 1 == nums[2]:
                            return True
        return False

    # Check 0 draws
    if check_mentsu(tiles):
        print(0)
        return

    # Check 1 draw
    for suit in ['m', 'p', 's']:
        for num in range(1, 10):
            new_tile = (num, suit)
            if check_mentsu(tiles + [new_tile]):
                print(1)
                return

    # If 0 or 1 draw doesn't work, minimum is 2
    # Because with 2 more tiles, we guarantee a mentsu.
    # Take the original 3 tiles (t1, t2, t3).
    # Draw t1 and t1. Now we have (t1, t2, t3, t1, t1).
    # We can form a koutsu (t1, t1, t1).
    print(2)

solve()
