def solve():
    n = int(input())
    s = input()

    golden_trophies = s.count('G')

    if golden_trophies == n:
        print(n)
        return
    if golden_trophies == 0:
        print(0)
        return

    segments = []
    current_segment_length = 0
    for char in s:
        if char == 'G':
            current_segment_length += 1
        else:
            if current_segment_length > 0:
                segments.append(current_segment_length)
            segments.append(0)
            current_segment_length = 0
    if current_segment_length > 0:
        segments.append(current_segment_length)
    if not segments:
        print(0)
        return

    max_beauty = 0
    for i in range(len(segments)):
        if segments[i] == 0:
            if i > 0 and i < len(segments) - 1:
                combined_length = segments[i-1] + segments[i+1]
                if golden_trophies > combined_length:
                    max_beauty = max(max_beauty, combined_length + 1)
                else:
                    max_beauty = max(max_beauty, combined_length)

            else:
                if i == 0 and len(segments) > 1:
                    if golden_trophies > segments[i+1]:
                        max_beauty = max(max_beauty, segments[i+1] + 1)
                    else:
                        max_beauty = max(max_beauty, segments[i+1])
                elif i == len(segments) - 1 and len(segments) > 1:
                    if golden_trophies > segments[i-1]:
                        max_beauty = max(max_beauty, segments[i-1] + 1)
                    else:
                        max_beauty = max(max_beauty, segments[i-1])
        else:
            if golden_trophies > segments[i]:
                max_beauty = max(max_beauty, segments[i] + 1)
            else:
                max_beauty = max(max_beauty, segments[i])

    print(max_beauty)

