def solve():
    board_str = [input() for _ in range(10)]
    board = [list(row) for row in board_str]

    def check_win(current_board):
        # Check rows
        for r in range(10):
            for c in range(10 - 4):
                if all(current_board[r][c+i] == 'X' for i in range(5)):
                    return True

        # Check columns
        for c in range(10):
            for r in range(10 - 4):
                if all(current_board[r+i][c] == 'X' for i in range(5)):
                    return True

        # Check diagonals (top-left to bottom-right)
        for r in range(10 - 4):
            for c in range(10 - 4):
                if all(current_board[r+i][c+i] == 'X' for i in range(5)):
                    return True

        # Check diagonals (top-right to bottom-left)
        for r in range(10 - 4):
            for c in range(4, 10):
                if all(current_board[r+i][c-i] == 'X' for i in range(5)):
                    return True
        return False

    for r in range(10):
        for c in range(10):
            if board[r][c] == '.':
                temp_board = [row[:] for row in board]
                temp_board[r][c] = 'X'
                if check_win(temp_board):
                    print("YES")
                    return

    print("NO")

solve()
