import math

def solve():
    l, r, x, y = map(int, input().split())

    if y % x != 0:
        print(0)
        return

    k = y // x
    count = 0

    upper_bound = int(math.sqrt(k))
    for a_prime in range(1, upper_bound + 1):
        if k % a_prime == 0:
            b_prime = k // a_prime

            if math.gcd(a_prime, b_prime) == 1:
                a = a_prime * x
                b = b_prime * x

                if l <= a <= r and l <= b <= r:
                    if a == b:
                        count += 1
                    else:
                        count += 2
    print(count)

