            temp_sum += a[j]
        else:
            if a[j] <= 20:
                temp_sum += factorials[a[j]]
                stickers_used += 1
            else:
                stickers_used = k + 1
                break

    if stickers_used <= k:
        if (temp_sum, stickers_used) not in left_sums:
            left_sums[(temp_sum, stickers_used)] = 0
        left_sums[(temp_sum, stickers_used)] += 1

for i in range(3 ** (n - half)):
    current_sum = 0
    stickers_used = 0
    temp_i = i
    for j in range(n - half):
        choice = temp_i % 3
        temp_i //= 3

        if choice == 0:
