from collections import defaultdict

a, b, c = map(int, input().split())
DIVISOR_MOD = 1073741824

def count_divisors(n_):
    count = defaultdict(int)
    d = 2
    temp = n_
    while d * d <= temp:
        while temp % d == 0:
            count[d] += 1
            temp //= d
        d += 1
    if temp > 1:
        count[temp] += 1

    num_divisors = 1
    for prime_count in count.values():
        num_divisors *= (prime_count + 1)

    return num_divisors

dp_divisors = {}
for i in range(1, max(a, b, c) * max(a, b, c) * max(a, b, c) + 1):
    dp_divisors[i] = count_divisors(i)

total_sum = 0
for i in range(1, a + 1):
    for j in range(1, b + 1):
        for k in range(1, c + 1):
            total_sum = (total_sum + dp_divisors[i * j * k]) % DIVISOR_MOD

print(total_sum)
