def solve():
    n = int(input())
    k_str = input()

    memo = {}

    def dp(index):
        if index == len(k_str):
            return [(0, 0)] 

        if index in memo:
            return memo[index]

        results = []
        for i in range(index, len(k_str)):
            val_str = k_str[index : i+1]
            if len(val_str) > 1 and val_str[0] == '0':
                continue

            val = int(val_str)
            if val >= n:
                continue

            for prev_sum, prev_power in dp(i+1):
                if prev_power > 18:
                    continue
                current_term = val * (n ** prev_power)

                if current_term + prev_sum > 10**18 and not (index == 0 and i == len(k_str) - 1):
                    continue

                results.append((current_term + prev_sum, prev_power + 1))

        memo[index] = results
        return results

    all_possible_sums = set()

    for s, p in dp(0):
        all_possible_sums.add(s)

    print(min(all_possible_sums))

solve()

