def solve():
    n, m = map(int, input().split())
    screen = [list(input()) for _ in range(n)]

    white_pixels = []
    for r in range(n):
        for c in range(m):
            if screen[r][c] == 'w':
                white_pixels.append((r, c))

    if not white_pixels:
        print(-1)
        return

    min_size = float('inf')
    best_frame = None

    for r1 in range(n):
        for c1 in range(m):
            for size in range(1, max(n, m) + 1):
                r2 = r1 + size - 1
                c2 = c1 + size - 1

                if not (0 <= r2 < n and 0 <= c2 < m):
                    continue

                frame_pixels = set()
                if size == 1:
                    frame_pixels.add((r1, c1))
                else:
                    for c_curr in range(c1, c2 + 1):
                        frame_pixels.add((r1, c_curr))
                        frame_pixels.add((r2, c_curr))
                    for r_curr in range(r1 + 1, r2):
                        frame_pixels.add((r_curr, c1))
                        frame_pixels.add((r_curr, c2))

                is_valid = True
                for wr, wc in white_pixels:
                    if (wr, wc) not in frame_pixels:
                        is_valid = False
                        break

                if is_valid:
                    white_on_frame = True
                    for wr, wc in white_pixels:
                        if (wr, wc) not in frame_pixels:
                            white_on_frame = False
                            break

                    if white_on_frame:
                        if size < min_size:
                            min_size = size
                            best_frame = (r1, c1, size)
                        elif size == min_size:
                            if best_frame is None or (r1, c1, size) < best_frame:
                                best_frame = (r1, c1, size)

    if best_frame is None:
        print(-1)
    else:
        br1, bc1, bsize = best_frame
        output_screen = [row[:] for row in screen]

        if bsize == 1:
            if output_screen[br1][bc1] != 'w':
                output_screen[br1][bc1] = '+'
        else:
            for c_curr in range(bc1, bc1 + bsize):
                if output_screen[br1][c_curr] != 'w':
                    output_screen[br1][c_curr] = '+'
                if output_screen[br1 + bsize - 1][c_curr] != 'w':
                    output_screen[br1 + bsize - 1][c_curr] = '+'
            for r_curr in range(br1 + 1, br1 + bsize - 1):
