def solve():
    n = int(input())
    cubes_data = []
    for _ in range(n):
        cubes_data.append(list(map(int, input().split())))

    def can_form(num_str, used_cubes, current_cube_index):
        if not num_str:
            return True

        if current_cube_index >= len(cubes_data):
            return False

        first_digit = int(num_str[0])

        # Try using the current cube for the first digit
        for face_digit in cubes_data[current_cube_index]:
            if face_digit == first_digit:
                if can_form(num_str[1:], used_cubes | {current_cube_index}, current_cube_index + 1):
                    return True

        # Try not using the current cube for the first digit
        return can_form(num_str, used_cubes, current_cube_index + 1)

    def can_make_number(num):
        s_num = str(num)
        k = len(s_num)

        if k == 1:
            for cube_faces in cubes_data:
                if int(s_num[0]) in cube_faces:
                    return True
            return False
        elif k == 2:
            for i in range(n):
                for j in range(n):
                    if i != j:
                        if int(s_num[0]) in cubes_data[i] and int(s_num[1]) in cubes_data[j]:
                            if s_num[0] != '0':
                                return True
            return False
        elif k == 3:
            for i in range(n):
                for j in range(n):
                    for l in range(n):
                        if i != j and i != l and j != l:
                            if int(s_num[0]) in cubes_data[i] and int(s_num[1]) in cubes_data[j] and int(s_num[2]) in cubes_data[l]:
                                if s_num[0] != '0':
                                    return True
            return False
        return False

    x = 0
    while True:
        target = x + 1
        if not can_make_number(target):
            break
        x += 1
    print(x)

