def solve():
    n = int(input())
    kuro_ribbon = input()
    shiro_ribbon = input()
    katie_ribbon = input()

    length = len(kuro_ribbon)

    def calculate_max_beauty(ribbon, num_turns, total_length):
        if num_turns >= total_length:
            return total_length

        from collections import Counter
        counts = Counter(ribbon)
        max_init_count = 0
        if counts:
            max_init_count = max(counts.values())

        if max_init_count == total_length:
            if num_turns == 1:
                return total_length - 1
            else:
                return total_length

        return min(max_init_count + num_turns, total_length)

    kuro_beauty = calculate_max_beauty(kuro_ribbon, n, length)
    shiro_beauty = calculate_max_beauty(shiro_ribbon, n, length)
    katie_beauty = calculate_max_beauty(katie_ribbon, n, length)

    max_overall_beauty = max(kuro_beauty, shiro_beauty, katie_beauty)

