def count_set_bits(n):
  count = 0
  while n > 0:
    n &= n - 1
    count += 1
  return count


def solve():
  if n == 1:
    return 1
  if n == 2:
    return 0
  if n == 3:
    return 0

  k = (n + 1) // 2
  if count_set_bits(k) == 1:
    return 1
  else:
    return 0


