def solve():
    x, y = map(int, input().split())

    if x == y:
        print(0)
        return

    memo = {}

    def dp(a, b, c):
        if a == y and b == y and c == y:
            return 0

        state = tuple(sorted((a, b, c)))
        if state in memo:
            return memo[state]

        min_ops = float('inf')

        # Try changing side a
        for new_a in range(y, max(1, min(a, b + c - 1)) + 1):
            if new_a != a:
                if b + c > new_a and a + c > b and a + b > c: # Check original
                    if b + c > new_a and new_a + c > b and new_a + b > c: # Check new
                        cost = 1 + dp(new_a, b, c)
                        min_ops = min(min_ops, cost)

        # Try changing side b
        for new_b in range(y, max(1, min(b, a + c - 1)) + 1):
            if new_b != b:
                if a + c > b and a + b > c and b + c > a: # Check original
                    if a + c > new_b and a + new_b > c and new_b + c > a: # Check new
                        cost = 1 + dp(a, new_b, c)
                        min_ops = min(min_ops, cost)

        # Try changing side c
        for new_c in range(y, max(1, min(c, a + b - 1)) + 1):
            if new_c != c:
                if a + b > c and a + c > b and b + c > a: # Check original
                    if a + b > new_c and a + new_c > b and new_c + b > a: # Check new
                        cost = 1 + dp(a, b, new_c)
                        min_ops = min(min_ops, cost)

        memo[state] = min_ops
        return min_ops

    initial_sides = [x, x, x]

    q = [(initial_sides, 0)]
    visited = {tuple(sorted(initial_sides))}

    while q:
        (a, b, c), steps = q.pop(0)

        if a == y and b == y and c == y:
            print(steps)
            return

        # Try changing side a
        for new_a in range(y, max(1, min(a - 1, b + c - 1)) + 1):
            if new_a < a and b + c > new_a and new_a + c > b and new_a + b > c:
                new_state = tuple(sorted((new_a, b, c)))
                if new_state not in visited:
                    visited.add(new_state)
                    q.append(((new_a, b, c), steps + 1))

        # Try changing side b
        for new_b in range(y, max(1, min(b - 1, a + c - 1)) + 1):
            if new_b < b and a + c > new_b and a + new_b > c and new_b + c > a:
                new_state = tuple(sorted((a, new_b, c)))
                if new_state not in visited:
                    visited.add(new_state)
                    q.append(((a, new_b, c), steps + 1))

        # Try changing side c
        for new_c in range(y, max(1, min(c - 1, a + b - 1)) + 1):
            if new_c < c and a + b > new_c and a + new_c > b and new_c + b > a:
                new_state = tuple(sorted((a, b, new_c)))
                if new_state not in visited:
                    visited.add(new_state)
                    q.append(((a, b, new_c), steps + 1))

solve()
