import sys

def solve():
    n, a, b = map(int, sys.stdin.readline().split())
    groups = list(map(int, sys.stdin.readline().split()))

    denied_count = 0
    seated_at_half_tables = 0  # Number of two-seater tables occupied by a single person

    for group_size in groups:
        if group_size == 1:
            if a > 0:
                a -= 1
            elif b > 0:
                b -= 1
                seated_at_half_tables += 1
            elif seated_at_half_tables > 0:
                seated_at_half_tables -= 1
            else:
                denied_count += 1
        else:  # group_size == 2
            if b > 0:
                b -= 1
            else:
                denied_count += 2

    sys.stdout.write(str(denied_count) + '\n')

solve()
